16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.temporal.ChronoUnit;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "birth_date")
59	    private LocalDate birthDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "membership_number")
71	    private String membershipNumber;
72	
73	    @Column(name = "bulk_signup_warning")
74	    private Boolean bulkSignupWarning;
75	
76	    @Column(name = "household_size")
77	    private Integer householdSize;
78	
79	    @Column(name = "postcode")
80	    private String postcode;
81	
82	    @Column(name = "possible_duplicate_of")
83	    private Integer possibleDuplicateOf;
84	
85	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
86	    private Set<Pet> pets;
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    /**
113	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
114	     * as the calling code, a space, then the national digits grouped in threes, e.g.
115	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
116	     */
117	    @Transient
118	    public String getTelephoneDisplay() {
119	        return TelephoneFormatter.toDisplay(this.telephone);
120	    }
121	
122	    public String getEmail() {
123	        return this.email;
124	    }
125	
126	    public void setEmail(String email) {
127	        this.email = email;
128	    }
129	
130	    public LocalDate getRegistrationDate() {
131	        return this.registrationDate;
132	    }
133	
134	    public void setRegistrationDate(LocalDate registrationDate) {
135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public LocalDate getBirthDate() {
139	        return this.birthDate;
140	    }
141	
142	    public void setBirthDate(LocalDate birthDate) {
143	        this.birthDate = birthDate;
144	    }
145	
146	    public String getCustomerCode() {
147	        return this.customerCode;
148	    }
149	
150	    public void setCustomerCode(String customerCode) {
151	        this.customerCode = customerCode;
152	    }
153	
154	    public String getHouseholdId() {
155	        return this.householdId;
156	    }
157	
158	    public void setHouseholdId(String householdId) {
159	        this.householdId = householdId;
160	    }
161	
162	    public Integer getNamesakeCount() {
163	        return this.namesakeCount;
164	    }
165	
166	    public void setNamesakeCount(Integer namesakeCount) {
167	        this.namesakeCount = namesakeCount;
168	    }
169	
170	    public String getMembershipNumber() {
171	        return this.membershipNumber;
172	    }
173	
174	    public void setMembershipNumber(String membershipNumber) {
175	        this.membershipNumber = membershipNumber;
176	    }
177	
178	    /**
179	     * Whether this owner was created after more than 80 owners had already been registered on the
180	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
181	     */
182	    public Boolean getBulkSignupWarning() {
183	        return this.bulkSignupWarning;
184	    }
185	
186	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
187	        this.bulkSignupWarning = bulkSignupWarning;
188	    }
189	
190	    /**
191	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
192	     * counting this owner) captured once at creation.
193	     */
194	    public Integer getHouseholdSize() {
195	        return this.householdSize;
196	    }
197	
198	    public void setHouseholdSize(Integer householdSize) {
199	        this.householdSize = householdSize;
200	    }
201	
202	    /**
203	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
204	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
205	     */
206	    public String getPostcode() {
207	        return this.postcode;
208	    }
209	
210	    public void setPostcode(String postcode) {
211	        this.postcode = postcode;
212	    }
213	
214	    /**
215	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
216	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
217	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
218	     * and a declared member is not a suspected duplicate — this is not populated at creation.
219	     * Captured once at creation.
220	     */
221	    public Integer getPossibleDuplicateOf() {
222	        return this.possibleDuplicateOf;
223	    }
224	
225	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
226	        this.possibleDuplicateOf = possibleDuplicateOf;
227	    }
228	
229	    /**
230	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
231	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
232	     */
233	    @Transient
234	    public Boolean getPossibleDuplicate() {
235	        return this.possibleDuplicateOf != null;
236	    }
237	
238	    /**
239	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
240	     */
241	    @Transient
242	    public String getDisplayName() {
243	        return this.getLastName() + ", " + this.getFirstName();
244	    }
245	
246	    /**
247	     * Return this owner's initials as the upper-cased first letters of the first and last
248	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
249	     */
250	    @Transient
251	    public String getInitials() {
252	        return initial(this.getFirstName()) + initial(this.getLastName());
253	    }
254	
255	    private static String initial(String name) {
256	        return Character.toUpperCase(name.charAt(0)) + ".";
257	    }
258	
259	    /** Points awarded when an email address is present. */
260	    private static final int EMAIL_POINTS = 2;
261	
262	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
263	    private static final int NO_NAMESAKE_POINTS = 1;
264	
265	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
266	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
267	
268	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
269	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
270	
271	    /** Points awarded for qualifying tenure. */
272	    private static final int TENURE_POINTS = 3;
273	
274	    /** The tenure, in days, that must be exceeded to earn {@link #TENURE_POINTS}. */
275	    private static final long MEMBERSHIP_TENURE_THRESHOLD_DAYS = 365;
276	
277	    /**
278	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
279	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
280	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
281	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
282	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days since registration).
283	     */
284	    @Transient
285	    public Integer getMembershipPoints() {
286	        int points = 0;
287	        if (hasEmail()) {
288	            points += EMAIL_POINTS;
289	        }
290	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
291	            points += NO_NAMESAKE_POINTS;
292	        }
293	        if (hasLargeHousehold()) {
294	            points += LARGE_HOUSEHOLD_POINTS;
295	        }
296	        if (hasQualifyingTenure()) {
297	            points += TENURE_POINTS;
298	        }
299	        return points;
300	    }
301	
302	    /**
303	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
304	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
305	     */
306	    @Transient
307	    public Integer getMembershipLevel() {
308	        int points = getMembershipPoints();
309	        if (points <= 1) {
310	            return 1;
311	        }
312	        if (points <= 3) {
313	            return 2;
314	        }
315	        if (points <= 5) {
316	            return 3;
317	        }
318	        return 4;
319	    }
320	
321	    /**
322	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
323	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
324	     * qualify.
325	     */
326	    private boolean hasLargeHousehold() {
327	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
328	    }
329	
330	    /**
331	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days, i.e.
332	     * more than that many days have elapsed since the {@code registrationDate}. Owners without a
333	     * registration date have no measurable tenure and do not qualify.
334	     */
335	    private boolean hasQualifyingTenure() {
336	        if (this.registrationDate == null) {
337	            return false;
338	        }
339	        long tenureDays = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
340	        return tenureDays > MEMBERSHIP_TENURE_THRESHOLD_DAYS;
341	    }
342	
343	    /** Whether this owner has a usable email address (present and not blank). */
344	    private boolean hasEmail() {
345	        return this.email != null && !this.email.isBlank();
346	    }
347	
348	    /**
349	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
350	     * present, otherwise {@code "PHONE"}.
351	     */
352	    @Transient
353	    public String getContactPreference() {
354	        return hasEmail() ? "EMAIL" : "PHONE";
355	    }
356	
357	    /**
358	     * Return this owner's age band derived from the {@code birthDate} as of the
359	     * {@code registrationDate}, or {@code null} when no birth date is known.
360	     */
361	    @Transient
362	    public AgeBand getAgeBand() {
363	        if (this.birthDate == null || this.registrationDate == null) {
364	            return null;
365	        }
366	        return AgeBand.asOf(this.birthDate, this.registrationDate);
367	    }
368	
369	    /**
370	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
371	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
372	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
373	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
374	     * region is resolved directly from the postcode and city.
375	     */
376	    @Transient
377	    public String getLocality() {
378	        if (this.customerCode == null) {
379	            return LocalityResolver.regionFor(this.postcode, this.city);
380	        }
381	        int separator = this.customerCode.indexOf('-');
382	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
383	    }
384	
385	    /**
386	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
387	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
388	     * known timezone.
389	     */
390	    @Transient
391	    public String getTimezone() {
392	        return LocalityResolver.timezoneFor(getLocality());
393	    }
394	
395	    /**
396	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
397	     * {@code customerCode}.
398	     */
399	    @Transient
400	    public Integer getCheckDigit() {
401	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
402	    }
403	
404	    /**
405	     * Return this owner's identity key, the single derived value all duplicate detection is based
406	     * on: the normalized telephone, email and household id joined with {@code '|'} as
407	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
408	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
409	     * because the telephone is part of the key, members of one household (same {@code householdId})
410	     * with different telephones have distinct keys and are not duplicates.
411	     */
412	    @Transient
413	    public String getIdentityKey() {
414	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
415	    }
416	
417	    private static String keyPart(String value) {
418	        return value == null ? "" : value;
419	    }
420	
421	    protected Set<Pet> getPetsInternal() {
422	        if (this.pets == null) {
423	            this.pets = new HashSet<>();
424	        }
425	        return this.pets;
426	    }
427	
428	    protected void setPetsInternal(Set<Pet> pets) {
429	        this.pets = pets;
430	    }
431	
432	    public List<Pet> getPets() {
433	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
434	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
435	        return Collections.unmodifiableList(sortedPets);
436	    }
437	
438	    public void setPets(List<Pet> pets) {
439	        this.pets = new HashSet<>(pets);
440	    }
441	
442	    public void addPet(Pet pet) {
443	        getPetsInternal().add(pet);
444	        pet.setOwner(this);
445	    }
446	
447	    /**
448	     * Return the Pet with the given name, or null if none found for this Owner.
449	     *
450	     * @param name to test
451	     * @return true if pet name is already in use
452	     */
453	    public Pet getPet(String name) {
454	        return getPet(name, false);
455	    }
456	
457	    /**
458	     * Return the Pet with the given name, or null if none found for this Owner.
459	     *
460	     * @param name to test
461	     * @return true if pet name is already in use
462	     */
463	    public Pet getPet(String name, boolean ignoreNew) {
464	        name = name.toLowerCase();
465	        for (Pet pet : getPetsInternal()) {
466	            if (!ignoreNew || !pet.isNew()) {
467	                String compName = pet.getName();
468	                compName = compName.toLowerCase();
469	                if (compName.equals(name)) {
470	                    return pet;
471	                }
472	            }
473	        }
474	        return null;
475	    }
476	
477	    public Pet getPet(Integer petId) {
478	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
479	    }
480	
481	    @Override
482	    public String toString() {
483	        return new ToStringCreator(this)
484	
485	            .append("id", this.getId())
486	            .append("new", this.isNew())
487	            .append("lastName", this.getLastName())
488	            .append("firstName", this.getFirstName())
489	            .append("address", this.address)
490	            .append("city", this.city)
491	            .append("telephone", this.telephone)
492	            .append("email", this.email)
493	            .append("registrationDate", this.registrationDate)
494	            .toString();
495	    }
496	}
