65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final OwnerFieldsValidator ownerFieldsValidator;
79	
80	    private final PostcodeValidator postcodeValidator;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final EmailNormalizer emailNormalizer;
85	
86	    private final AddressNormalizer addressNormalizer;
87	
88	    private final BusinessDayResolver businessDayResolver;
89	
90	    private final OwnerAuditLogger ownerAuditLogger;
91	
92	    private final HouseholdIdGenerator householdIdGenerator;
93	
94	    /** Maximum number of owners a single city may hold before further creations are rejected. */
95	    static final long MAX_OWNERS_PER_CITY = 50;
96	
97	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
98	    static final long MAX_OWNERS_PER_DAY = 100;
99	
100	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
101	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
102	
103	    public OwnerRestControllerV1(ClinicService clinicService,
104	                                 OwnerMapper ownerMapper,
105	                                 PetMapper petMapper,
106	                                 VisitMapper visitMapper,
107	                                 OwnerFieldsValidator ownerFieldsValidator,
108	                                 PostcodeValidator postcodeValidator,
109	                                 TelephoneNormalizer telephoneNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 AddressNormalizer addressNormalizer,
112	                                 BusinessDayResolver businessDayResolver,
113	                                 OwnerAuditLogger ownerAuditLogger,
114	                                 HouseholdIdGenerator householdIdGenerator) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	        this.ownerFieldsValidator = ownerFieldsValidator;
120	        this.postcodeValidator = postcodeValidator;
121	        this.telephoneNormalizer = telephoneNormalizer;
122	        this.emailNormalizer = emailNormalizer;
123	        this.addressNormalizer = addressNormalizer;
124	        this.businessDayResolver = businessDayResolver;
125	        this.ownerAuditLogger = ownerAuditLogger;
126	        this.householdIdGenerator = householdIdGenerator;
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
132	        Collection<Owner> owners;
133	        if (lastName != null) {
134	            owners = this.clinicService.findOwnerByLastName(lastName);
135	        } else {
136	            owners = this.clinicService.findAllOwners();
137	        }
138	        if (owners.isEmpty()) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
157	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
158	        this.ownerFieldsValidator.validate(ownerFieldsDto);
159	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
160	        HttpHeaders headers = new HttpHeaders();
161	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
162	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
163	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
164	        LocalDate serverDate = LocalDate.now();
165	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
166	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
167	        }
168	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
169	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
170	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
171	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
172	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
173	        }
174	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
175	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
176	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
177	        }
178	        if (owner.getPostcode() != null) {
179	            owner.setHouseholdId(this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
180	        }
181	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
182	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
183	        }
184	        Owner householdDuplicate = this.clinicService.findHouseholdDuplicateOf(owner);
185	        if (householdDuplicate != null && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
186	            throw new DuplicateHouseholdException(owner.getHouseholdId());
187	        }
188	        this.clinicService.saveOwner(owner);
189	        this.ownerAuditLogger.logCreated(owner);
190	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
191	        headers.setLocation(UriComponentsBuilder.newInstance()
192	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
193	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
194	    }
