219	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	        }
221	        this.clinicService.deleteOwner(owner);
222	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        HttpHeaders headers = new HttpHeaders();
233	        Pet pet = petMapper.toPet(petFieldsDto);
234	        owner.setId(ownerId);
235	        pet.setOwner(owner);
236	        pet.getType().setName(null);
237	        this.clinicService.savePet(pet);
238	        PetDto petDto = petMapper.toPetDto(pet);
239	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
240	            .buildAndExpand(pet.getId()).toUri());
241	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
247	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
248	        if (currentOwner != null) {
249	            Pet currentPet = this.clinicService.findPetById(petId);
250	            if (currentPet != null) {
251	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
252	                currentPet.setName(petFieldsDto.getName());
253	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
254	                this.clinicService.savePet(currentPet);
255	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
256	            }
257	        }
258	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	    }
260	
261	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
262	    @Override
263	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
264	        HttpHeaders headers = new HttpHeaders();
265	        Visit visit = visitMapper.toVisit(visitFieldsDto);
